	@Test
	void localStatementConversionPreservesAnInlinedAliasAcrossCompositions() {
		Object epoch = new Object();
		var repository = new SailRepository(new NativeStore(temporary.toFile()));
		repository.init();
		try (var connection = repository.getConnection()) {
			var local = repository.getValueFactory();
			var plain = SimpleValueFactory.getInstance();
			var allocation = new BlankNodeAllocationScope();
			allocation.bindLocalValueFactory(local);
			Value remote = plain.createBNode("remote-local-control");
			Value alias = RemoteBNode.newResponseScope(allocation, local, epoch, true).map(remote);
			connection.add(plain.createIRI("urn:local"), plain.createIRI("urn:p"), alias);
			for (String pattern : List.of("?local <urn:p> ?node",
					"{ ?local <urn:p> ?node } UNION { ?local <urn:p> ?node }",
					"?local <urn:p> ?node OPTIONAL { ?local <urn:absent> ?other }",
					"{ SELECT ?node WHERE { ?local <urn:p> ?node } }")) {
				var query = connection.prepareTupleQuery("SELECT ?node WHERE { " + pattern + " } ORDER BY ?node");
				query.setBinding("node", alias);
				int count = 0;
				try (var rows = query.evaluate()) {
					while (rows.hasNext()) {
						Value actual = rows.next().getValue("node");
						assertEquals(alias, actual, pattern);
						assertInstanceOf(RemoteBNode.class, actual,
								"local matching must retain the optimizer-inlined binding's authority: " + pattern);
						assertEquals(remote, RemoteBNode.toRemoteValue(actual, epoch, true, true), pattern);
						count++;
					}
				}
				assertEquals(pattern.contains("UNION") ? 2 : 1, count, pattern);
			}
		} finally {
			repository.shutDown();
		}
	}

